      undofile = true;
      swapfile = false;
      encoding = "utf-8";
      cursorline = true;
      fileformat = "unix";
      number = true;
      relativenumber = false;
      splitbelow = true;
      splitright = true;
      clipboard = "unnamedplus";
      ignorecase = true;
      smartcase = true;
      hlsearch = true;
      incsearch = true;
      mouse = "a";
      mousefocus = true;
      expandtab = true;
      shiftwidth = 4;
      tabstop = 4;
      softtabstop = 4;
      smartindent = true;
      cindent = true;
      smarttab = true;
      scroll = 30;
      shortmess = "c";
      termguicolors = true;
    };

    # Fillchars
    opts.fillchars = {
      vert = "│";
      fold = "⠀";
      eob = " ";
      msgsep = "‾";
      foldopen = "▾";
      foldsep = "│";
      foldclose = "▸";
    };

    # Extra Lua config - custom commands and LSP for nix
    extraConfigLua = ''
      -- Fillcolors highlight clear
      vim.cmd([[highlight clear LineNr]])
      vim.cmd([[highlight clear SignColumn]])

      -- LSP настройка для Nix (nixd)
      vim.api.nvim_create_autocmd('FileType', {
        pattern = 'nix',
        callback = function()
          vim.lsp.start({ name = 'nixd', cmd = { 'nixd' } })
        end,
      })

      -- Функция для добавления '# type: ignore'
      local function add_type_ignore()
        local line = vim.api.nvim_get_current_line()
        local new_line = line .. ' # type: ignore'
        vim.api.nvim_set_current_line(new_line)
      end

      -- Команда ':Tyig'
      vim.api.nvim_create_user_command('Tyig', add_type_ignore, {})

      -- Автосет filetype для .dy файлов
      vim.api.nvim_create_autocmd({"BufRead", "BufNewFile"}, {
        pattern = "*.dy",
        command = "set filetype=python",
      })

      vim.api.nvim_create_autocmd({"BufRead", "BufNewFile"}, {
        pattern = "*.py",
        command = "set filetype=python",
      })

      -- LSP Debug Info
      function _G.LspDebugInfo()
        print("Current filetype: " .. vim.bo.filetype)
        local clients = vim.lsp.get_clients()
        if #clients == 0 then
          print("No active LSP clients.")
        else
          print("Active LSP clients:")
          for _, client in ipairs(clients) do
            print("- " .. client.name .. " (id: " .. client.id .. ")")
          end
        end
      end

      vim.api.nvim_create_user_command('LspDebugInfo', _G.LspDebugInfo, {
        desc = 'Display LSP Debug Information (filetype and active clients)',
      })
    '';

    # Keymaps
    keymaps = [
      # Quit
      { key = "<C-q>"; action = ":q<CR>"; }
      # Copy all text
      { key = "<C-a>"; action = "%y+<CR>"; }
      # Save
      { mode = "i"; key = "<C-s>"; action = ":w<CR>"; }
      { mode = "n"; key = "<C-s>"; action = ":w<CR>"; }
      # NvimTree
      { key = "<leader>t"; action = ":NvimTreeToggle<CR>"; }
      { key = "<leader>tf"; action = ":NvimTreeFocus<CR>"; }
      # Type ignore
      { key = "<leader>h"; action = ":Tyig<CR>"; }
      # BufferLine
      { key = "<Tab>"; action = ":BufferLineCycleNext<CR>"; }
      { key = "<leader><Tab>"; action = ":BufferLineCyclePrev<CR>"; }
      { key = "<C-H>"; action = ":BufferLineCloseOthers<CR>"; }
      { key = "<leader><Esc>"; action = ":bd<CR>"; }
      # TodoList
      { key = "<leader>nl"; action = ":TodoTelescope<CR>"; }
      # ToggleTerm
      { key = "<leader>s"; action = ":ToggleTerm direction=float<CR>"; }
      # Telescope
      { key = "<leader>ff"; action = "<cmd>Telescope find_files<CR>"; }
      { key = "<leader>ft"; action = "<cmd>Telescope live_grep<CR>"; }
      { key = "<leader>fb"; action = "<cmd>Telescope buffers<CR>"; }
      { key = "<leader>fh"; action = "<cmd>Telescope help_tags<CR>"; }
      # Git
      { key = "<leader>gb"; action = "<cmd>Telescope git_branches<CR>"; }
      { key = "<leader>gc"; action = "<cmd>Telescope git_commits<CR>"; }
      { key = "<leader>gs"; action = "<cmd>Telescope git_status<CR>"; }
      # Colorscheme
      { key = "<leader>cs"; action = "<cmd>Telescope colorscheme<CR>"; }
      # LSP diagnostics
      { key = "<space>e"; action = "<cmd>lua vim.diagnostic.open_float()<CR>"; }
      { key = "<C-[>"; action = "<cmd>lua vim.diagnostic.goto_prev()<CR>"; }
      { key = "<C-]>"; action = "<cmd>lua vim.diagnostic.goto_next()<CR>"; }
      # LSP actions (buffer-local, set via LspAttach)
      { mode = "n"; key = "<C-d>"; action = "<cmd>lua vim.lsp.buf.declaration()<CR>"; }
      { mode = "n"; key = "<C-l>"; action = "<cmd>lua vim.lsp.buf.definition()<CR>"; }
      { mode = "n"; key = "<C-f>"; action = "<cmd>lua vim.lsp.buf.hover()<CR>"; }
      { mode = "n"; key = "i"; action = "<cmd>lua vim.lsp.buf.implementation()<CR>"; }
      { mode = "n"; key = "<C-r>"; action = "<cmd>lua vim.lsp.buf.signature_help()<CR>"; }
      { mode = "n"; key = "<space>r"; action = "<cmd>lua vim.lsp.buf.code_action()<CR>"; }
      { mode = "n"; key = "gr"; action = "<cmd>lua vim.lsp.buf.references()<CR>"; }
      { mode = "n"; key = "<space>f"; action = "<cmd>lua vim.lsp.buf.format({async=true})<CR>"; }
      # Terminal keymaps
      { mode = "t"; key = "<esc>"; action = "<C-\\><C-n>"; }
      { mode = "t"; key = "jk"; action = "<C-\\><C-n>"; }
    ];

    # Plugins
    plugins = {
      # Treesitter
      treesitter = {
        enable = true;
        settings = {
          ensure_installed = [
            "bash" "css" "dockerfile" "html" "javascript" "json" "json5"
            "lua" "python" "vim" "yaml" "c" "go" "rust"
          ];
          highlight.enable = true;
          auto_install = true;
        };
      };

      # LSP
      lsp = {
        enable = true;
        servers = {
          nixd.enable = true;
          pyright.enable = true;
          ruff.enable = true;
          ts_ls.enable = true;
          gopls.enable = true;
          rust_analyzer.enable = true;
          bashls.enable = true;
          cssls.enable = true;
          html.enable = true;
          jsonls.enable = true;
          yamlls.enable = true;
          dockerls.enable = true;
          lua_ls.enable = true;
          emmet_ls.enable = true;
        };
      };

      # Mason
      mason = {
        enable = true;
        settings = {
          ui = {
            icons = {
              package_installed = "✓";
              package_pending = "➜";
              package_uninstalled = "✗";
            };
          };
        };
      };

      mason-lspconfig.enable = true;

      # CMP (autocomplete)
      cmp = {
        enable = true;
        settings = {
          snippet.expand = "function(args) require('luasnip').lsp_expand(args.body) end";
          window = {
            completion = lib.nixvim.mkRaw "cmp.config.window.bordered()";
            documentation = lib.nixvim.mkRaw "cmp.config.window.bordered()";
          };
          mapping = lib.nixvim.mkRaw ''
            cmp.mapping.preset.insert({
              ['<C-b>'] = cmp.mapping.scroll_docs(-4),
              ['<C-f>'] = cmp.mapping.scroll_docs(4),
              ['<C-e>'] = cmp.mapping.abort(),
              ['<CR>'] = cmp.mapping.confirm({select = true}),
              ["<Tab>"] = cmp.mapping(function(fallback)
                if cmp.visible() then
                  cmp.select_next_item()
                else
                  fallback()
                end
              end, {"i", "s"}),
              ["<S-Tab>"] = cmp.mapping(function(fallback)
                if cmp.visible() then
                  cmp.select_prev_item()
                else
                  fallback()
                end
              end, {"i", "s"})
            })
          '';
          sources = lib.nixvim.mkRaw ''
            cmp.config.sources({
              {name = 'nvim_lsp'},
              {name = 'luasnip'},
              {name = "path"}
            }, {
              {name = 'buffer'},
              {name = 'nvim_lsp_signature_help'}
            })
          '';
        };
      };

      cmp-nvim-lsp.enable = true;
      cmp-buffer.enable = true;
      cmp-path.enable = true;
      cmp-cmdline.enable = true;
      luasnip.enable = true;

      # Telescope
      telescope = {
        enable = true;
      };

      # NvimTree
      nvim-tree = {
        enable = true;
      };

      # Lualine
      lualine.enable = true;

      # Cellular automaton
      cellular-automaton.enable = true;

      # Colorizer
      colorizer.enable = true;

      # Todo comments
      todo-comments.enable = true;

      # Gruvbox (available but not default)
      gruvbox.enable = true;

      # Catppuccin
      catppuccin.enable = true;

      # Better escape
      better-escape = {
        enable = true;
        settings = {
          mapping = ["jk"];
          timeout = lib.nixvim.mkRaw "vim.o.timeoutlen";
          clear_empty_lines = false;
          keys = "<Esc>";
        };
      };

      # Comment
      comment.enable = true;

      # Bufferline
      bufferline = {
        enable = true;
      };

      # ALE (linter)
      ale = {
        enable = true;
        settings = {
          linters = {
            python = ["mypy"];
          };
        };
      };

      # vim-illuminate
      illuminate.enable = true;

      # Trouble
      trouble.enable = true;

      # ToggleTerm
      toggleterm = {
        enable = true;
      };

      # Which-Key
      which-key = {
        enable = true;
        settings = {
          timeout = 100;
        };
      };

      # Mini plugins
      mini = {
        enable = true;
        modules = {
          move = {};
          pairs = {};
        };
      };

      # Dashboard
      dashboard = {
        enable = true;
      };
    };

    # Extra plugins without modules
    extraPlugins = with pkgs.vimPlugins; [
      plenary-nvim
      nvim-web-devicons
    ];
  };
}

