      { key = "<space>e"; action = "<cmd>lua vim.diagnostic.open_float()<CR>"; }
      { key = "<C-[>"; action = "<cmd>lua vim.diagnostic.goto_prev()<CR>"; }
      { key = "<C-]>"; action = "<cmd>lua vim.diagnostic.goto_next()<CR>"; }
      # LSP actions (buffer-local, set via LspAttach)
      { mode = "n"; key = "<C-d>"; action = "<cmd>lua vim.lsp.buf.declaration()<CR>"; }
      { mode = "n"; key = "<C-l>"; action = "<cmd>lua vim.lsp.buf.definition()<CR>"; }
      { mode = "n"; key = "<C-f>"; action = "<cmd>lua vim.lsp.buf.hover()<CR>"; }
      { mode = "n"; key = "i"; action = "<cmd>lua vim.lsp.buf.implementation()<CR>"; }
      { mode = "n"; key = "<C-r>"; action = "<cmd>lua vim.lsp.buf.signature_help()<CR>"; }
      { mode = "n"; key = "<space>r"; action = "<cmd>lua vim.lsp.buf.code_action()<CR>"; }
      { mode = "n"; key = "gr"; action = "<cmd>lua vim.lsp.buf.references()<CR>"; }
      { mode = "n"; key = "<space>f"; action = "<cmd>lua vim.lsp.buf.format({async=true})<CR>"; }
      # Terminal keymaps
      { mode = "t"; key = "<esc>"; action = "<C-\\><C-n>"; }
      { mode = "t"; key = "jk"; action = "<C-\\><C-n>"; }
    ];

    # Plugins
    plugins = {
      # Treesitter
      treesitter = {
        enable = true;
        settings = {
          ensure_installed = [
            "bash" "css" "dockerfile" "html" "javascript" "json" "json5"
            "lua" "python" "vim" "yaml" "c" "go" "rust" "nix"
          ];
          highlight.enable = true;
          auto_install = true;
        };
      };

      # LSP
      lsp = {
        enable = true;
        servers = {
          nixd.enable = true;
          pyright.enable = true;
          ruff.enable = true;
          ts_ls.enable = true;
          gopls.enable = true;
          rust_analyzer.enable = true;
          bashls.enable = true;
          cssls.enable = true;
          html.enable = true;
          jsonls.enable = true;
          yamlls.enable = true;
          dockerls.enable = true;
          lua_ls.enable = true;
          emmet_ls.enable = true;
        };
      };

      # LSP signature
      lsp-signature.enable = true;

      # CMP (autocomplete) - используем blink-cmp
      blink-cmp = {
        enable = true;
        settings = {
          snippets = {
            preset = "luasnip";
          };
          completion = {
            accept = {
              auto_brackets = {
                enabled = true;
              };
            };
          };
          appearance = {
            use_nvim_cmp_as_default = true;
          };
        };
      };

      luasnip = {
        enable = true;
        settings = {
          from_lua = [
            {
              paths = "./snippets";
            }
          ];
        };
      };

      # Telescope
      telescope = {
        enable = true;
        keymaps = {
          "<leader>ff" = "find_files";
          "<leader>ft" = "live_grep";
          "<leader>fb" = "buffers";
          "<leader>fh" = "help_tags";
          "<leader>gb" = "git_branches";
          "<leader>gc" = "git_commits";
          "<leader>gs" = "git_status";
          "<leader>cs" = "colorscheme";
        };
      };

      # NvimTree
      nvim-tree = {
        enable = true;
      };

      # Lualine
      lualine = {
        enable = true;
      };

      # Colorizer
      colorizer = {
        enable = true;
      };

      # Todo comments
      todo-comments = {
        enable = true;
      };

      # Comment
      comment = {
        enable = true;
      };

      # Bufferline
      bufferline = {
        enable = true;
      };

      # Better escape
      better-escape = {
        enable = true;
      };

      # Trouble
      trouble = {
        enable = true;
      };

      # ToggleTerm
      toggleterm = {
        enable = true;
      };

      # Which-Key
      which-key = {
        enable = true;
        settings = {
          timeout = 100;
        };
      };

      # Mini plugins
      mini = {
        enable = true;
        modules = {
          move = {};
          pairs = {};
        };
      };

      # Dashboard
      dashboard = {
        enable = true;
      };

      # Illuminate (подсветка одинаковых слов)
      illuminate = {
        enable = true;
      };
    };

    # Extra plugins без модулей
    extraPlugins = with pkgs.vimPlugins; [
      plenary-nvim
      nvim-web-devicons
      ale  # Linter
      cellular-automaton
    ];
  };
}

